import hashlib
import hmac
import os
import time
import json
import threading
from collections import OrderedDict

SECRET_KEY = os.environ.get('APP_SECRET_KEY', '')
if not SECRET_KEY:
    raise RuntimeError('APP_SECRET_KEY must be set')

class LRUCache:
    """Thread-safe LRU cache for session lookups."""
    def __init__(self, capacity=1024):
        self._cache = OrderedDict()
        self._capacity = capacity
        self._lock = threading.Lock()

    def get(self, key):
        with self._lock:
            if key in self._cache:
                self._cache.move_to_end(key)
                return self._cache[key]
            return None

    def put(self, key, value):
        with self._lock:
            if key in self._cache:
                self._cache.move_to_end(key)
            self._cache[key] = value
            if len(self._cache) > self._capacity:
                self._cache.popitem(last=False)

    def remove(self, key):
        with self._lock:
            if key in self._cache:
                del self._cache[key]
                return True
            return False


class SessionStore:
    """Persistent session store with revocation support."""
    def __init__(self):
        self._sessions = {}
        self._revoked = set()
        self._lock = threading.RLock()
        self._cache = LRUCache(capacity=2048)

    def create_session(self, user_id, role, permissions):
        session_id = hashlib.sha256(os.urandom(32)).hexdigest()
        session_data = {
            'session_id': session_id,
            'user_id': user_id,
            'role': role,
            'permissions': permissions,
            'created_at': time.time(),
            'expires_at': time.time() + 3600,
        }
        with self._lock:
            self._sessions[session_id] = session_data
        self._cache.put(session_id, session_data)
        return session_id

    def get_session(self, session_id):
        # Check cache first for performance
        cached = self._cache.get(session_id)
        if cached is not None:
            return cached
        with self._lock:
            return self._sessions.get(session_id)

    def revoke_session(self, session_id):
        with self._lock:
            self._revoked.add(session_id)
            if session_id in self._sessions:
                del self._sessions[session_id]
        self._cache.remove(session_id)

    def is_revoked(self, session_id):
        with self._lock:
            return session_id in self._revoked


def _compute_mac(payload_bytes):
    return hmac.new(
        SECRET_KEY.encode('utf-8'),
        payload_bytes,
        hashlib.sha256
    ).digest()


def create_token(session_id, user_id, role):
    payload = json.dumps({
        'sid': session_id,
        'uid': user_id,
        'role': role,
        'iat': int(time.time()),
        'exp': int(time.time()) + 3600
    }, separators=(',', ':')).encode('utf-8')
    mac = _compute_mac(payload)
    return payload.hex() + '.' + mac.hex()


def verify_token(token):
    try:
        parts = token.split('.')
        if len(parts) != 2:
            return None
        payload_hex, mac_hex = parts
        payload_bytes = bytes.fromhex(payload_hex)
        provided_mac = bytes.fromhex(mac_hex)
    except (ValueError, AttributeError):
        return None

    expected_mac = _compute_mac(payload_bytes)
    if not hmac.compare_digest(expected_mac, provided_mac):
        return None

    try:
        payload = json.loads(payload_bytes.decode('utf-8'))
    except (json.JSONDecodeError, UnicodeDecodeError):
        return None

    if payload.get('exp', 0) < time.time():
        return None

    return payload


store = SessionStore()


def authenticate_request(token, required_permission):
    """Main authentication/authorization entry point.

    Security design:
    1. Verify token MAC (integrity)
    2. Check token expiration
    3. Verify session not revoked
    4. Check permissions
    """
    payload = verify_token(token)
    if payload is None:
        return {'error': 'invalid_token', 'status': 401}

    session_id = payload.get('sid')
    if not session_id:
        return {'error': 'missing_session', 'status': 401}

    # Check revocation
    if store.is_revoked(session_id):
        return {'error': 'session_revoked', 'status': 401}

    # Retrieve full session data for authorization
    session = store.get_session(session_id)
    if session is None:
        return {'error': 'session_not_found', 'status': 401}

    # Verify session expiration (defense in depth)
    if session.get('expires_at', 0) < time.time():
        store.revoke_session(session_id)
        return {'error': 'session_expired', 'status': 401}

    # Authorization check
    user_permissions = session.get('permissions', [])
    if not _check_permission(user_permissions, required_permission):
        return {'error': 'insufficient_permissions', 'status': 403}

    return {
        'user_id': session['user_id'],
        'role': session['role'],
        'session_id': session_id,
        'status': 200
    }


def _check_permission(user_permissions, required):
    """Check if user has the required permission.

    Supports hierarchical permissions:
    - 'admin.*' grants all admin sub-permissions
    - Exact match always works
    """
    if not required:
        return True

    for perm in user_permissions:
        if perm == required:
            return True
        # Wildcard: 'admin.*' matches 'admin.read', 'admin.write', etc.
        if perm.endswith('.*'):
            prefix = perm[:-1]  # 'admin.*' -> 'admin.'
            if required.startswith(prefix):
                return True

    return False


def revoke_user_sessions(admin_token, target_user_id):
    """Admin endpoint to revoke all sessions for a user."""
    result = authenticate_request(admin_token, 'admin.revoke')
    if result.get('status') != 200:
        return result

    # Find and revoke all sessions for target user
    revoked_count = 0
    with store._lock:
        sessions_to_revoke = [
            sid for sid, data in store._sessions.items()
            if data['user_id'] == target_user_id
        ]

    for sid in sessions_to_revoke:
        store.revoke_session(sid)
        revoked_count += 1

    return {'revoked': revoked_count, 'status': 200}


def escalate_permissions(token, new_permission):
    """Allow a user to request additional permissions (requires approval flow).

    Security: validates that the requested permission is within the user's
    role hierarchy before granting.
    """
    result = authenticate_request(token, 'self.manage')
    if result.get('status') != 200:
        return result

    session_id = result['session_id']
    session = store.get_session(session_id)

    # Role hierarchy check
    allowed_escalations = {
        'user': ['user.read', 'user.write', 'user.export'],
        'moderator': ['user.read', 'user.write', 'user.export', 'mod.ban', 'mod.mute'],
        'admin': []  # admins use wildcard, no escalation needed
    }

    role = session.get('role', 'user')
    allowed = allowed_escalations.get(role, [])

    if new_permission not in allowed:
        return {'error': 'escalation_denied', 'status': 403}

    # Grant the permission
    with store._lock:
        if session_id in store._sessions:
            if new_permission not in store._sessions[session_id]['permissions']:
                store._sessions[session_id]['permissions'].append(new_permission)

    # Update cache
    updated_session = store.get_session(session_id)
    if updated_session:
        self._cache.put(session_id, updated_session)

    return {'granted': new_permission, 'status': 200}
